// Finite original teaching examples. Rules only: no model, network or arbitrary generation.
const q=(text,choices,answer,explanation,why,steps,extra={})=>({question:text,choices,answer,explanation,why,steps,...extra});
const mathSteps=[{question:'“平均分”要让什么一样？',choices:['每份的数量一样','每份的颜色一样'],answer:'每份的数量一样',explanation:'平均分比较的是数量，每份要一样多。'},{question:'怎样检查每份的数量？',choices:['每份数量 × 份数 = 总数','总数 + 份数'],answer:'每份数量 × 份数 = 总数',explanation:'把每份合起来，应当正好回到总数。'}];
const chineseSteps=[{question:'先看题目在比较哪一方面？',choices:['题目描述的特点','字的笔画多少'],answer:'题目描述的特点',explanation:'反义词要在同一个方面比较，不能按笔画判断。'},{question:'怎样检查反义词？',choices:['放回两种情境，意思相反','读音相近就可以'],answer:'放回两种情境，意思相反',explanation:'放回情境里检查意思，读音相近不等于意思相反。'}];
const englishSteps=[{question:'a / an 主要看什么？',choices:['后一个词开头的音素','单词有几个字母'],answer:'后一个词开头的音素',explanation:'这里根据开头的发音选择，不按字母数量。'},{question:'开头是元音音素时，用哪个？',choices:['an','a'],answer:'an',explanation:'元音音素前用 an；辅音音素前用 a。'}];
export const loopBank={
 math:{label:'数学',topic:'平均分',items:[
 q('12 颗糖平均分给 3 人，每人几颗？',['3','4','6','9'],'4','12 ÷ 3 = 4；检查 4 × 3 = 12。',{'3':'你选了 3，它是人数；题目问每人分到的颗数。','6':'你选了 6，但 6 × 3 = 18，比总数 12 多。','9':'你选了 9，12 − 3 = 9 是减掉一次，不是分成相同的 3 份。'},mathSteps,{total:12,groups:3}),
 q('20 块积木平均放入 4 个盒子，每盒几块？',['4','5','10','16'],'5','20 ÷ 4 = 5；检查 5 × 4 = 20。',{'4':'4 是盒子个数，4 × 4 = 16，不等于 20。','10':'10 × 4 = 40，超过了 20。','16':'20 − 4 = 16 不是平均分成 4 份。'},mathSteps,{total:20,groups:4}),
 q('18 支笔平均装进 6 个袋子，每袋几支？',['3','6','12','18'],'3','18 ÷ 6 = 3；检查 3 × 6 = 18。',{'6':'6 是袋子个数，6 × 6 = 36，不等于 18。','12':'18 − 6 = 12 不是平均分成 6 份。','18':'18 是总数；每袋都放 18 支会超过总数。'},mathSteps,{total:18,groups:6})]},
 chinese:{label:'语文',topic:'情境反义词',items:[
 q('大箱子要两手抱，小箱子一手能拿。与“大”相反的是？',['小','多','长','高'],'小','这里比较箱子大小，“大”和“小”意思相反。',{'多':'“多”说数量，这里比较的是箱子大小。','长':'“长”说长度，这里比较的是大小。','高':'“高”说高度，这里比较的是大小。'},chineseSteps),
 q('一条路很宽，另一条路只容一人通过。与“宽”相反的是？',['窄','短','少','低'],'窄','这里比较道路宽窄，“宽”和“窄”意思相反。',{'短':'“短”说长度，这里比较道路宽窄。','少':'“少”说数量，这里比较道路宽窄。','低':'“低”说高度，这里比较道路宽窄。'},chineseSteps),
 q('满水的桶很重，空桶拿起来很轻。与“重”相反的是？',['轻','少','短','低'],'轻','这里比较重量，“重”和“轻”意思相反。',{'少':'“少”说数量，这里比较重量。','短':'“短”说长度，这里比较重量。','低':'“低”说高度，这里比较重量。'},chineseSteps)]},
 english:{label:'英语',topic:'a / an',items:[
 q('一只猫：___ cat',['a','an'],'a','cat 开头为辅音音素 /k/，用 a。',{'an':'你选了 an；cat 开头的 /k/ 是辅音音素，不是元音音素。'},englishSteps),
 q('一个橘子：___ orange',['a','an'],'an','orange 开头为元音音素（英式 /ɒ/），用 an。',{'a':'你选了 a；orange 开头为元音音素，应检查 an 的规则。'},englishSteps),
 q('一把伞：___ umbrella',['a','an'],'an','umbrella 开头为元音音素 /ʌ/，用 an。',{'a':'你选了 a；umbrella 开头的 /ʌ/ 是元音音素。'},englishSteps)]}
};
export function boundedDivision(total,groups){if(!Number.isSafeInteger(total)||!Number.isSafeInteger(groups)||total<1||total>100||groups<1||groups>10||total%groups!==0)throw Error('Outside finite integer division scope');return total/groups;}
for(const q of loopBank.math.items)if(String(boundedDivision(q.total,q.groups))!==q.answer)throw Error('Invalid authored math');
const own=(o,k)=>Object.hasOwn(o,k);
export const isLoopSubject=k=>typeof k==='string'&&own(loopBank,k);
export function localDay(at=new Date()){const d=new Date(at);if(!Number.isFinite(d.getTime()))throw Error('Invalid date');return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
export function addDays(day,days){if(!validDay(day)||!Number.isInteger(days)||days<0||days>30)throw Error('Invalid day interval');const [y,m,d]=day.split('-').map(Number);return localDay(new Date(y,m-1,d+days,12));}
function validDay(d){if(typeof d!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(d))return false;const [y,m,n]=d.split('-').map(Number);return y>=2000&&y<=2200&&localDay(new Date(y,m-1,n,12))===d;}
const stamp=at=>new Date(at).toISOString();
const validStamp=value=>typeof value==='string'&&Number.isFinite(Date.parse(value))&&new Date(value).toISOString()===value;
const state=p=>p.learningLoop??=({version:1,nextId:1,runs:[],reviews:{}});
export function getLoop(p,subject,kind='practice'){if(!isLoopSubject(subject)||!['practice','review'].includes(kind))return null;return p.learningLoop?.runs.filter(r=>r.subject===subject&&r.kind===kind).at(-1)||null;}
export function startLoop(p,subject,{kind='practice',at=new Date(),restart=false}={}){if(!isLoopSubject(subject)||!['practice','review'].includes(kind))return null;const day=localDay(at),s=state(p),existing=getLoop(p,subject,kind);if(existing&&(!existing.completedAt||!restart))return existing;const task=s.reviews[subject];if(kind==='review'&&!task)return null;const r={id:`loop-${s.nextId++}-${globalThis.crypto?.randomUUID?.()||Math.random().toString(36).slice(2)}`,subject,kind,phase:'initial',selected:null,revision:0,answers:[],guides:[],startedAt:stamp(at),completedAt:null,reviewDue:kind==='review'?task.due:null,early:kind==='review'&&day<task.due,schedule:null};s.runs.push(r);return r;}
export function loopQuestion(r){return loopBank[r.subject].items[r.kind==='review'?2:r.phase==='transfer'||r.phase==='complete'?1:0];}
export function answerQuestion(r,a){return loopBank[r.subject].items[a.role==='transfer'?1:r.kind==='review'?2:0];}
export function loopReason(r){const a=r.answers[0],q=answerQuestion(r,a||{role:'first'});if(!a)return '';return a.choice===null?'这次选择了“我还不会”。先从一个小问题开始。':a.correct?'首次选择正确。':q.why[a.choice];}
function finish(p,r,at){r.phase='complete';r.selected=null;r.completedAt=stamp(at);const last=r.answers.at(-1),independent=last.role!=='retry'&&last.correct;const proposed=addDays(localDay(at),independent?3:1),s=state(p),old=s.reviews[r.subject];let due=proposed;if(r.kind==='review'&&localDay(at)<(old?.due||r.reviewDue)){const previous=old?.due||r.reviewDue;due=previous<proposed?previous:proposed;}else if(r.kind==='practice'&&old)due=old.due<proposed?old.due:proposed;s.reviews[r.subject]={due,sourceId:r.id};r.schedule={due,days:independent?3:1,keptDue:due!==proposed};}
// Each rendered control carries the revision: stale/double submits cannot advance a later stage.
export function loopAction(p,id,revision,action,value=null,at=new Date()){const r=p.learningLoop?.runs.find(r=>r.id===id);if(!r||r.completedAt||r.revision!==revision)return false;const q=loopQuestion(r);let ok=false;
 if(action==='select'&&['initial','retry','transfer'].includes(r.phase)&&q.choices.includes(value)){r.selected=value;ok=true;}
 if((action==='submit'||action==='skip')&&['initial','retry','transfer'].includes(r.phase)&&(action==='skip'||q.choices.includes(r.selected))){const role=r.phase==='initial'?'first':r.phase,choice=action==='skip'?null:r.selected,correct=choice===q.answer;r.answers.push({role,choice,correct,at:stamp(at),assisted:role==='retry'});r.selected=null;if(role==='first'){if(correct){if(r.kind==='review')finish(p,r,at);else r.phase='transfer';}else r.phase='guide1';}else if(role==='retry'&&r.kind==='practice')r.phase='transfer';else finish(p,r,at);ok=true;}
 if(action==='guide'&&['guide1','guide2'].includes(r.phase)){const i=r.phase==='guide1'?0:1,step=q.steps[i];if(r.guides.length===i&&step.choices.includes(value)){r.guides.push({choice:value,correct:value===step.answer,at:stamp(at)});ok=true;}}
 if(action==='next'&&['guide1','guide2'].includes(r.phase)&&r.guides.length===(r.phase==='guide1'?1:2)){r.phase=r.phase==='guide1'?'guide2':'retry';ok=true;}
 if(ok)r.revision++;return ok;
}
export function reviewLists(p,at=new Date()){const day=localDay(at),entries=Object.entries(p.learningLoop?.reviews||{}).map(([subject,t])=>({subject,...t}));return {day,due:entries.filter(t=>t.due<=day).sort((a,b)=>a.due.localeCompare(b.due)),future:entries.filter(t=>t.due>day).sort((a,b)=>a.due.localeCompare(b.due))};}
export function loopEvidence(p){return (p.learningLoop?.runs||[]).map(r=>({run:r,first:r.answers.find(a=>a.role==='first'),retry:r.answers.find(a=>a.role==='retry'),transfer:r.answers.find(a=>a.role==='transfer'),wrongs:r.answers.filter(a=>!a.correct)}));}
// Optional extension: malformed new data must not destroy valid pre-existing practice/test data.
export function validLoopState(s){try{if(!s||s.version!==1||!Number.isSafeInteger(s.nextId)||s.nextId<1||!Array.isArray(s.runs)||!s.reviews||Array.isArray(s.reviews))return false;const ids=new Set();for(const r of s.runs){if(!r||!isLoopSubject(r.subject)||!['practice','review'].includes(r.kind)||!/^loop-[1-9]\d*(?:-[a-z0-9-]+)?$/.test(r.id)||ids.has(r.id)||Number.parseInt(r.id.slice(5),10)>=s.nextId||!['initial','guide1','guide2','retry','transfer','complete'].includes(r.phase)||!Number.isSafeInteger(r.revision)||r.revision<0||!Array.isArray(r.answers)||!Array.isArray(r.guides)||r.guides.length>2||!validStamp(r.startedAt)||typeof r.early!=='boolean')return false;ids.add(r.id);if((r.kind==='review'&&!validDay(r.reviewDue))||(r.kind==='practice'&&(r.reviewDue!==null||r.early))||(r.kind==='review'&&r.phase==='transfer'))return false;const q=loopQuestion(r);if(r.selected!==null&&(!['initial','retry','transfer'].includes(r.phase)||!q.choices.includes(r.selected)))return false;const roles=r.answers.map(a=>a.role).join(',');const allowed=r.kind==='review'?['','first','first,retry']:['','first','first,retry','first,transfer','first,retry,transfer'];if(!allowed.includes(roles))return false;for(const a of r.answers){const aq=answerQuestion(r,a);if(!(a.choice===null||aq.choices.includes(a.choice))||a.correct!==(a.choice===aq.answer)||a.assisted!==(a.role==='retry')||!validStamp(a.at))return false;}for(const [i,g] of r.guides.entries()){const step=q.steps[i];if(!step.choices.includes(g.choice)||g.correct!==(g.choice===step.answer)||!validStamp(g.at))return false;}const first=r.answers[0],retry=r.answers.find(a=>a.role==='retry'),transfer=r.answers.find(a=>a.role==='transfer');if(r.phase==='initial'&&(r.answers.length||r.guides.length))return false;if(['guide1','guide2','retry'].includes(r.phase)&&(!first||first.correct||retry||transfer))return false;if(r.phase==='guide1'&&r.guides.length>1||r.phase==='guide2'&&r.guides.length<1||r.phase==='retry'&&r.guides.length!==2)return false;if(retry&&(r.guides.length!==2||first?.correct)||first?.correct&&r.guides.length)return false;if(transfer&&(!first||(!first.correct&&!retry)))return false;if(r.kind==='review'&&r.early!==(localDay(r.startedAt)<r.reviewDue))return false;if(r.phase==='transfer'&&(!first||(!first.correct&&!retry)||transfer))return false;if(r.phase==='complete'){if(!validStamp(r.completedAt)||!r.schedule||!validDay(r.schedule.due)||![1,3].includes(r.schedule.days)||typeof r.schedule.keptDue!=='boolean'||(r.kind==='practice'?!transfer:(!first?.correct&&!retry)))return false;}else if(r.completedAt!==null||r.schedule!==null)return false;}
 return Object.entries(s.reviews).every(([k,t])=>isLoopSubject(k)&&t&&validDay(t.due)&&s.runs.some(r=>r.id===t.sourceId&&r.subject===k&&r.completedAt));}catch{return false;}}
